mapper.select:
SELECT DISTINCT ia.fund_cd AS fundCd , ia.fund_nm AS fundNm , ia.fund_nm AS xxFundCd , ia.mg_cd AS mgCd , F_FUND_COLOR(#{corpGr}, ia.fund_cd, TO_DATE(REPLACE(REPLACE(#{ymd}, '-', ''), '.', ''), 'YYYYMMDD')) AS fundColor , ia.enc_acct_no AS encAcctNo , TO_DECRYPTS(ia.enc_acct_no) AS acctNo , TO_CHAR(ia.fst_seolj_ymd, 'YYYY-MM-DD') AS fstSeoljYmd , TO_CHAR(t2.bf_gyul_ymd, 'YYYY-MM-DD') AS bfGyulYmd , TO_CHAR(t2.haeji_ymd, 'YYYY-MM-DD') AS haejiYmd FROM SZM0IA ia , SZM0GI t2 WHERE ia.corp_gr = #{corpGr}
AND ia.mg_cd = #{mgCd}
AND ia.mg_cd LIKE '%'
AND NVL(ia.haeji_ymd, TO_DATE(REPLACE(REPLACE(#{ymd}, '-', ''), '.', ''), 'YYYYMMDD') + 1) > TO_DATE(REPLACE(REPLACE(#{ymd}, '-', ''), '.', ''), 'YYYYMMDD') AND t2.corp_gr = ia.corp_gr AND t2.fund_cd = ia.fund_cd AND TO_DATE(REPLACE(REPLACE(#{ymd}, '-', ''), '.', ''), 'YYYYMMDD') Between (t2.bf_gyul_ymd + 1) AND t2.af_gyul_ymd ORDER BY ia.mg_cd, ia.fund_cd
